<template>
	<div>

		<!--  <div>库存预警提醒</div>-->
		<div>
			<el-button type="primary" icon="el-icon-refresh" size="small" @click="getTableData()">刷新
			</el-button>
			<el-button type="info" icon="el-icon-download" size="small" @click="exportDataEvent">导出</el-button>
			<el-select v-model="searchFilter.account" filterable placeholder="选择查询字段"
				style="margin-left:15px;width: 150px;" size="small">
				<el-option v-for="item in list" :key="item.id" :label="item.value" :value="item.value">
				</el-option>
			</el-select>
			<el-input style="margin-left:5px;width: 150px;" size="small" :placeholder="chanpin()"
				v-model="searchFilter.name" clearable @clear="clear"></el-input>
			<el-autocomplete style="margin-left:5px;width: 130px;" class="inline-input" v-model="searchFilter.disable"
				:fetch-suggestions="querySearch" placeholder="类型？" size="small">
				<i class="el-icon-circle-close el-input__icon" slot="suffix" @click="qinchu()">
				</i>
			</el-autocomplete>
			<el-date-picker style="margin-left:5px;margin-top:10px;width: 250px;" size="small"
				v-model="searchFilter.riqi" type="daterange" :picker-options="pickerOptions" range-separator="至"
				start-placeholder="开始日期" end-placeholder="结束日期" align="right" unlink-panels value-format="yyyy-MM-dd">
			</el-date-picker>
			<el-button style="margin-left:5px; margin-top:10px;" type="primary" icon="el-icon-search" size="small" plain
				@click="handleSearch">搜索</el-button>
			<el-button style="margin-top:10px;" type="primary" icon="el-icon-zoom-out" size="small" plain
				@click="clearFilter()">清空条件</el-button>
		</div>
		<vxe-table style="margin-top: 10px;" border stripe resizable highlight-hover-row highlight-current-row
			align="center" :height="tableHeight" :loading="loading" row-id="id" :print-config="{}" :data="tableData"
			:expand-config="{ accordion: true, iconOpen: 'fa fa-minus-square', iconClose: 'fa fa-plus-square', toggleMethod: toggleExpandMethod }"
			ref="xTable1" id="dy1">
			<!-- <vxe-table-column type="expand" width="50" title="展开"> 
						<template #content="{ }">
							<div class="expand-wrapper">

								<vxe-table border highlight-hover-row highlight-current-row align="center"
									:data="childData">
									<vxe-table-column type="seq" width="50" title="序号"></vxe-table-column>
									
									<vxe-column field="产品ID[0].产品ID" title="产品ID" :visible="false"></vxe-column>
									<vxe-column field="产品ID[0].产品名称" title="产品名称"></vxe-column>
									<vxe-column field="型号" title="型号"></vxe-column>
									<vxe-column field="规格" title="规格"></vxe-column>
									<vxe-column field="品牌" title="品牌"></vxe-column>
									<vxe-column field="单位" title="单位"></vxe-column>
									
									<vxe-column field="库存" title="库存数量" width="110"></vxe-column>
									<vxe-column field="货位号" title="货位号" width="110"></vxe-column>
								</vxe-table>
							</div>
						</template>
</vxe-table-column> -->
			<vxe-table-column type="seq" width="50" title="序号"></vxe-table-column>
			<vxe-table-column field="id" title="id" :visible="false"></vxe-table-column>
			<!-- <vxe-column field='单据编号' title='单据编号'></vxe-column> -->
			<vxe-table-column field="类型" title="类型"></vxe-table-column>
			<vxe-column :field="this.searchFilter.name != '' ? '产品名称' : '产品名称'" title="产品名称"></vxe-column>
			<vxe-column :field="this.searchFilter.name != '' ? '型号' : '型号'" title="型号"></vxe-column>
			<vxe-column :field="this.searchFilter.name != '' ? '规格' : '规格'" title="规格"></vxe-column>
			<vxe-column :field="this.searchFilter.name != '' ? '单位' : '单位'" title="单位"></vxe-column>
			<!-- <vxe-column field="单价" title="单价" width="110"></vxe-column> -->
			<vxe-column field="数量" title="数量" width="110"></vxe-column>
			<!-- <vxe-column field="金额" title="金额" width="110">
								<template #default="{ row }">
									<span>{{ row.单价*row.数量 }}</span>
								</template>
							</vxe-column> -->
			<vxe-column field="货位号" title="货位号" width="110"></vxe-column>
			<vxe-table-column field="日期" title="日期"></vxe-table-column>

		</vxe-table>
		<vxe-pager :loading="loading" :current-page="tablePage.currentPage" :page-size="tablePage.pageSize"
			:total="tablePage.totalResult"
			:layouts="['PrevPage', 'JumpNumber', 'NextPage', 'FullJump', 'Sizes', 'Total']"
			@page-change="handlePageChange">
		</vxe-pager>

	</div>
</template>

<script>
import setter from '@/libs/setter.js'
import {
	Query,
	Aud,
} from '@api/shuju.js'
import {
	mapState,
	mapActions
} from 'vuex'
export default {
	name: 'Quer',
	components: {

	},
	props: {
		tablename: String,
		type: Array
	},
	data() {
		return {
			authKeys: [], //用户的权限数组
			uuid: '',
			cplist: [],
			khList: [],
			isDev: false,
			fullscreenLoading: false,
			tableHeight: 0, //表格高度
			alldata: [],
			tableData: [], //表内数据	相当于layuidata	
			childData: [], //子表数据	相当于soulTable子表	
			name: `"${this.tablename}"`,
			loading: false, //是否显示加载中
			tablePage: { // 分页属性---
				currentPage: 1, //当前页 相当于layui的page
				pageSize: 10, //每页条数 相当于layui的limt
				totalResult: 0, //总页数   相当于count			
			},

			searchFilter: {
				name: '',
				account: '产品名称',
				riqi: [this.$XEUtils.toDateString(new Date(), 'yyyy-MM-dd'), this.$XEUtils.toDateString(new Date(), 'yyyy-MM-dd')],
				disable: ''
			},
			isShow: true,
			disables: [],
			arr3: [],
			arr1: [],
			arr2: [],
			buzou: 3,
			leixz: '',
			list: [{
				id: 0,
				value: '产品ID'
			},
			{
				id: 1,
				value: '产品名称'
			},

			],
			pickerOptions: {
				shortcuts: [{
					text: '最近一周',
					onClick(picker) {
						const end = new Date();
						const start = new Date();
						start.setTime(start.getTime() - 3600 * 1000 * 24 * 7);
						picker.$emit('pick', [start, end]);
					}
				}, {
					text: '最近一个月',
					onClick(picker) {
						const end = new Date();
						const start = new Date();
						start.setTime(start.getTime() - 3600 * 1000 * 24 * 30);
						picker.$emit('pick', [start, end]);
					}
				}, {
					text: '最近三个月',
					onClick(picker) {
						const end = new Date();
						const start = new Date();
						start.setTime(start.getTime() - 3600 * 1000 * 24 * 90);
						picker.$emit('pick', [start, end]);
					}
				}]
			},
			active: 1
		}
	},

	mounted() {
		this.checkDev();
		this.getAuthKeys();


	},
	created() {
		this.disables = this.type
	},
	computed: {
		...mapState('d2admin/user', [
			'info'
		])
	},
	methods: {
		chanpin() {
			return `请输入${this.searchFilter.account}`
		},

		getAuthKeys() {
			// setTimeout(() => {
			// 	this.getTableData()
			// }, 200)

			this.authKeys = ['超级管理员', '开票员'].includes(this.info.role)
		},
		async getTableData() {
			console.log(this.searchFilter)
			let tj = `状态 == -1  AND    完成 ==-1 `

			let tjy
			let tjz
			let filter
			let set = new Set()
			let CPID = []
			if (this.searchFilter.riqi) {

				tjz = `日期 >= '${this.searchFilter.riqi[0]}' AND 日期 <= '${this.searchFilter.riqi[1]}'`
				tj += ' AND ' + tjz
			}
			if (this.searchFilter.disable != '') {
				tjy = `类型 == '${this.searchFilter.disable}'`
				tj += ' AND ' + tjy
			}
			if (this.searchFilter.name != '') {

				filter = `"${this.searchFilter.account}"  LIKE '%${this.searchFilter.name}%'`
				tj += ' AND ' + filter
			}
			console.log(tj)
			Query({
				tj: tj,
				tablename: this.name,
				order: 'DESC',
				field: 'id',
				page: this.tablePage.currentPage,
				limit: this.tablePage.pageSize
			})
				.then(res => {
					console.log(res)
					this.tableData = Object.freeze(res.data)
					this.tablePage.totalResult = res.count
					this.loading = false
				})
				.catch(err => {
					// 异常情况
					this.loading = false
				})


		},
		toggleExpandMethod({
			expanded,
			row
		}) {
			// this.loading = true
			if (expanded) {
				console.log(row.产品ID)
				let account
				if (this.searchFilter.account == '') {
					account = '产品名称'
				} else {
					account = this.searchFilter.account
				}

				Query({
					type: 'kucun',

					where: {
						match: {
							产品ID: row.产品ID
						},
						// filter: `${new RegExp(`${this.searchFilter.name}`, 'i')}.test(${account})&& 启用== "-1"`,
						hw: true,
						sort: { 日期: 1 }
					},

				})
					.then(res => {
						console.log(res.data)
						this.childData = Object.freeze(res.data)
						// this.loading = false
					})
					.catch(err => {
						// 异常情况

					})
			}
			return true

		},

		checkDev() {
			this.isDev = (process.env.NODE_ENV === 'development') ? true : false
		},



		handleSearch() {

			this.tablePage.currentPage = 1 //注意要回来第一页
			this.getTableData()

			this.tablePage.currentPage = 1 //注意要回来第一页
			this.getTableData()

		},
		handlePageChange({
			currentPage,
			pageSize
		}) {
			this.tablePage.currentPage = currentPage
			this.tablePage.pageSize = pageSize
			this.getTableData()
		},
		clearFilter() {
			let obj = this.searchFilter
			for (let key in obj) {
				this.searchFilter
				obj[key] = ''
			}
		},

		exportDataEvent() {
			this.$refs.xTable1.exportData({
				type: 'csv'
			})
		},
		exportDataEvent2() {
			this.$refs.xTable2.exportData({
				type: 'csv'
			})
		},
		querySearch(queryString, cb) {
			console.log(this.type)
			let values = this.type; //传入下拉列表数组
			let results = queryString ? values.filter(this.createFilter(queryString)) : values;
			// 调用 callback 返回建议列表的数据
			cb(results);
		},
		createFilter(queryString) {
			return (e) => {
				return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
			}
		},
		qinchu() {
			let obj = this.searchFilter
			obj['disable'] = ''

		},
		clear() {
			let obj = this.searchFilter
			obj['name'] = ''
		}
	}
}
</script>

