import {
    Query,
    Aud
} from '@api/shuju.js'
export default {
    getTime() {
        var date = new Date();
        //var bh1 = date.getFullYear().toString();
        var bh2 = (date.getMonth() + 1).toString();
        var bh3 = date.getDate().toString();
        var bh4 = date.getHours().toString();
        var bh5 = date.getMinutes().toString();
        var bh6 = date.getSeconds().toString();
        bh2.length < 2 ? bh2 = '0' + bh2 : bh2;
        bh3.length < 2 ? bh3 = '0' + bh3 : bh3;
        bh4.length < 2 ? bh4 = '0' + bh4 : bh4;
        bh5.length < 2 ? bh5 = '0' + bh5 : bh5;
        bh6.length < 2 ? bh6 = '0' + bh6 : bh6;
        //var d = date.getFullYear() + "-" + (date.getMonth() + 1) + "-" + date.getDate() + " " +date.getHours()+ ":" + date.getMinutes()+":"+date.getSeconds();
        var d = date.getFullYear() + "-" + bh2 + "-" + bh3 + " " + bh4 + ":" + bh5 + ":" + bh6;
        return d;
    },
    ToString(n) {

        if (!/^(0|[1-9]\d*)(\.\d+)?$/.test(n)) {
            return "数据非法";  //判断数据是否大于0
        }

        var unit = "千百拾亿千百拾万千百拾元角分", str = "";
        n += "00";

        var indexpoint = n.indexOf('.');  // 如果是小数，截取小数点前面的位数

        if (indexpoint >= 0) {

            n = n.substring(0, indexpoint) + n.substr(indexpoint + 1, 2);   // 若为小数，截取需要使用的unit单位
        }

        unit = unit.substr(unit.length - n.length);  // 若为整数，截取需要使用的unit单位
        for (var i = 0; i < n.length; i++) {
            str += "零壹贰叁肆伍陆柒捌玖".charAt(n.charAt(i)) + unit.charAt(i);  //遍历转化为大写的数字
        }

        return str.replace(/零(千|百|拾|角)/g, "零").replace(/(零)+/g, "零").replace(/零(万|亿|元)/g, "$1").replace(/(亿)万|壹(拾)/g, "$1$2").replace(/^元零?|零分/g, "").replace(/元$/g, "元整"); // 替换掉数字里面的零字符，得到结果

    },
    uniarr(arr, field) {
        let MAP = new Map()
        arr.forEach(function (element) {

            MAP.set(element[field], element)
        })

        return Array.from(MAP.values())
    },
    gettablelist(tbale_name) {
        let tablelist = Query({
            content: `PRAGMA table_info(${tbale_name})`,
            tj: 'for'
        }).then(resx => {
            let list = resx.data.map((item) => {
                if (item.name != 'id') {
                    return item.name
                }
            })
            return list.filter(Boolean)
        })
        return tablelist
    },
    heji(arr) {
        let add = arr.reduce(function (sum, item) {
            return sum + item;
        }, 0);
        return add
    }
}